    {
      name: 'text_transform',
      description:
        'Transform text by uppercase, lowercase, or slug mode. Optional trim (default true).',
      inputSchema: TEXT_TRANSFORM_SCHEMA,
    },
  ];
}

function fail(message) {
  throw new Error(message);
}

function validateTextTransform(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    fail('Invalid arguments: expected an object');
  }
  const allowed = Object.keys(TEXT_TRANSFORM_SCHEMA.properties);
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      fail(`Invalid argument: ${key}`);
    }
  }
  const { text, mode, trim } = args;
  if (typeof text !== 'string') {
    fail('Invalid argument: text must be a string');
  }
  if (typeof mode !== 'string' || !MODES.includes(mode)) {
    fail('Invalid argument: mode must be one of uppercase, lowercase, slug');
  }
  if (trim !== undefined && typeof trim !== 'boolean') {
    fail('Invalid argument: trim must be a boolean');
  }
  return { text, mode, trim: trim === undefined ? true : trim };
}

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    fail(`Unknown tool: ${name}`);
  }
  const { text, mode, trim } = validateTextTransform(args);

  let value = trim ? text.trim() : text;
  if (mode === 'uppercase') {
