import('./server.mjs').then(async ({callTool, listTools}) => {
  const t = async (name, args) => { try { const r = await callTool(name, args); return r.content[0].text; } catch(e){ return 'ERR:'+e.message; } };
  console.log('uppercase:', await t('text_transform',{text:'  Hi  ',mode:'uppercase'}));
  console.log('uppercase no-trim:', await t('text_transform',{text:'  Hi  ',mode:'uppercase',trim:false}));
  console.log('lowercase:', await t('text_transform',{text:'HeLLo',mode:'lowercase'}));
  console.log('slug multi:', await t('text_transform',{text:'  Hello,,, World!!!  ',mode:'slug'}));
  console.log('slug trim false still trims:', await t('text_transform',{text:'  A  B  ',mode:'slug',trim:false}));
  console.log('missing mode:', await t('text_transform',{text:'x'}));
  console.log('missing text:', await t('text_transform',{mode:'lowercase'}));
  console.log('bad mode:', await t('text_transform',{text:'x',mode:'foo'}));
  console.log('extra arg:', await t('text_transform',{text:'x',mode:'lowercase',foo:1}));
  console.log('bad trim:', await t('text_transform',{text:'x',mode:'lowercase',trim:'yes'}));
  console.log('unknown tool:', await t('nope',{text:'x',mode:'lowercase'}));
  console.log('tools:', JSON.stringify((await listTools())[0].inputSchema));
});
""}

